<script setup lang="ts">
import TypeLink from '../TypeLink.vue';
import {apiEntries} from '../apiCatalog';
import {typeDocs} from '../typeDocs';
import type {ComponentContract,DefaultValue} from './types';
defineProps<{components:ComponentContract[]}>();
function related(component:ComponentContract){const text=JSON.stringify(component);return Object.keys(typeDocs).filter(name=>new RegExp('\\b'+name+'\\b').test(text));}
function fallback(value:DefaultValue){return value.kind==='required'?'Required':value.kind==='omitted'?'Not set':value.kind==='derived'?value.expression:value.value;}
</script>
<template><section v-for="component in components" :key="component.source" class="documentation-api"><h2>{{ component.name }}</h2><p class="documentation-source">{{ component.source }}</p><p v-if="component.forwardsAttrs">Native attributes and listeners are forwarded to the component root unless explicitly bound to its inner element. Use accessible labels for inputs and icon-only controls.</p><template v-if="component.structure?.length"><h3>Structure</h3><p>Generated from the component template. Conditional and repeated elements describe possible structure.</p><pre class="documentation-structure">{{ component.structure.join('\n') }}</pre></template><template v-if="component.props.length"><h3>Properties</h3><div class="documentation-table"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr v-for="prop in component.props" :key="prop.name"><td><code>{{ prop.name }}</code></td><td><code>{{ prop.type }}</code><div class="documentation-references"><TypeLink v-for="name in prop.references.filter(name=>Object.prototype.hasOwnProperty.call(typeDocs,name))" :key="name" :name="name"/></div></td><td><code>{{ fallback(prop.default) }}</code></td><td>{{ prop.description }}</td></tr></tbody></table></div></template><template v-for="section in ([{title:'Emits',items:component.emits},{title:'Slots',items:component.slots},{title:'Exposed API',items:component.methods}])" :key="section.title"><template v-if="section.items.length"><h3>{{ section.title }}</h3><div class="documentation-table"><table><thead><tr><th>Name</th><th>Parameters</th><th>Return type</th><th>Description</th></tr></thead><tbody><tr v-for="item in section.items" :key="item.name"><td><code>{{ item.name }}</code><small v-if="item.kind==='property'"> Exposed value</small></td><td><code>{{ item.parameters||'None' }}</code></td><td><code>{{ item.returns }}</code></td><td>{{ item.description }}</td></tr></tbody></table></div></template></template><template v-if="related(component).length"><h3>Related interfaces and types</h3><div class="documentation-table"><table><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr v-for="name in related(component)" :key="name"><td><TypeLink :name="name"/></td><td>{{ apiEntries.find(entry=>entry.name===name)?.kind??'Type' }}</td><td>Not applicable to a type definition</td><td>{{ typeDocs[name]?.description }}</td></tr></tbody></table></div></template></section></template>
